package com.minhnb.finvera_be.research.service;import com.minhnb.finvera_be.research.domain.DocumentType;import com.minhnb.finvera_be.research.repository.ResearchDocumentRepository;import java.time.*;import java.util.*;import org.springframework.data.domain.PageRequest;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
/** Published metadata-only research facts; document content never crosses this boundary. */@Service public class ResearchAlertDataService{private final ResearchDocumentRepository repo;public ResearchAlertDataService(ResearchDocumentRepository r){repo=r;}public record Fact(UUID id,UUID instrumentId,String title,String category,String source,LocalDate publicationDate,Instant acceptedAt){}@Transactional(readOnly=true)public List<Fact> findAfter(UUID owner,UUID instrument,DocumentType type,Instant after,UUID afterId,int limit){return repo.findAcceptedAfter(owner,instrument,type,after,afterId,PageRequest.of(0,limit)).stream().map(d->new Fact(d.getId(),d.getSymbolId(),d.getTitle(),d.getDocumentType().name(),d.getSource(),d.getPublicationDate(),d.getProcessedAt())).toList();}}
